import glob, json, os, re, sqlite3, collections
CERTAIN = {"static", "dynamic"}
WORDS = {"test", "tests", "testing", "tester", "testutil"}
def conv(p):
    return any(x in p for x in ("__tests__", ".test.", ".spec.", "/test/", "/tests/", "/testsuite/")) or p.startswith(("test/", "tests/", "__tests__/", "testsuite/"))
def word(p):
    for piece in re.split(r"[/._\-]", p):
        s = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", piece)
        s = re.sub(r"(?<=[A-Z])(?=[A-Z][a-z])", " ", s)
        for t in s.split():
            if t.lower() in WORDS:
                return t
    return None
def undetermined(p, flag):
    return flag == 0 and not conv(p) and word(p) is not None
def store(repo):
    d = glob.glob("/private/tmp/TEST-EDGE-SCOPE-1B-%s-before/databases/*.db" % repo)
    assert len(d) == 1, (repo, d)
    assert not (os.path.exists(d[0] + "-wal") and os.path.getsize(d[0] + "-wal") > 0), ("uncheckpointed WAL", repo)
    c = sqlite3.connect("file:" + d[0] + "?immutable=1", uri=True)
    s = c.execute("select snapshot_uid from snapshots where status='ready' order by created_at desc limit 1").fetchone()[0]
    return c, s
def facts(repo):
    c, s = store(repo)
    kind, qn, fu = {}, {}, {}
    for u, k, q, f in c.execute("select node_uid, kind, qualified_name, file_uid from nodes where snapshot_uid=? and kind in ('FILE','MODULE')", (s,)):
        kind[u] = k; qn[u] = q; fu[u] = f
    flag = {f: t for f, t in c.execute("select file_uid, is_test from files")}
    path = {f: p for f, p in c.execute("select file_uid, path from files")}
    owner, imports = {}, []
    for a, b, ty, r in c.execute("select source_node_uid, target_node_uid, type, resolution from edges where snapshot_uid=? and type in ('OWNS','IMPORTS')", (s,)):
        if ty == "OWNS":
            owner[b] = a
        elif kind.get(a) == "FILE" and kind.get(b) == "FILE":
            assert r in ("static", "dynamic", "inferred"), ("resolution outside the vocabulary", r)
            imports.append((a, b, r))
    cand = collections.defaultdict(set)
    for f, m in c.execute("select o.file_uid, mc.canonical_root_path from module_file_ownership o join module_candidates mc on mc.module_candidate_uid=o.module_candidate_uid where o.snapshot_uid=?", (s,)):
