def cell(F, a, r):
    t = F["flag"].get(F["fu"][a])
    return ("test" if t == 1 else "prod", "inferred" if r == "inferred" else "certain")
def admitted(cl, tests, inferred):
    return (cl[0] == "prod" or tests) and (cl[1] == "certain" or inferred)
def candidate_cells(F):
    cells = collections.defaultdict(collections.Counter)
    for a, b, r in F["imports"]:
        for x in F["cand"].get(F["fu"][a], ()):
            for y in F["cand"].get(F["fu"][b], ()):
                if x != y:
                    cells[(x, y)][cell(F, a, r)] += 1
    return cells
def view_edges(cells, tests, inferred):
    out = []
