def sccs(adj):
    index, low, on, stack, out, i = {}, {}, set(), [], [], 0
    nodes = sorted(set(adj) | {w for v in adj.values() for w in v})
    for root in nodes:
        if root in index:
            continue
        work = [(root, iter(sorted(adj.get(root, ()))))]
        index[root] = low[root] = i; i += 1; stack.append(root); on.add(root)
        while work:
            v, it = work[-1]
            nxt = next(it, None)
            if nxt is not None:
                if nxt not in index:
                    index[nxt] = low[nxt] = i; i += 1; stack.append(nxt); on.add(nxt)
                    work.append((nxt, iter(sorted(adj.get(nxt, ())))))
